script.lang:
-- Insert into amp_org_group INSERT INTO amp_org_group (amp_org_grp_id, org_grp_name, org_grp_code, org_type) VALUES ((SELECT nextval('AMP_ORG_GROUP_seq')), 'Undefined Agencies', 'UA', 3);
-- Insert into amp_organisation
INSERT INTO amp_organisation (amp_org_id, name, org_code, org_grp_id) SELECT nextval('AMP_ORGANISATION_seq'), 'Undefined Agency', 'UA', (SELECT amp_org_grp_id FROM amp_org_group WHERE org_grp_name = 'Undefined Agencies' LIMIT 1) WHERE NOT EXISTS (SELECT 1 FROM amp_organisation WHERE name = 'Undefined Agency');
